


DELETE FROM REPORT_JSON WHERE REPORT_ID IN (100,200,300) AND PRODUCT_ID=<PRODUCT_ID_VALUE>;

VALUES(<PRODUCT_ID_VALUE>, 100, 5100, '{"DB_TYPE": "4", "HEADING": [[{"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Date/Time", "ROWSPAN": "1"}, {"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Received", "ROWSPAN": "1"}, {"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Answered", "ROWSPAN": "1"}, {"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Disconnected", "ROWSPAN": "1"}, {"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Completed", "ROWSPAN": "1"}, {"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Rejected", "ROWSPAN": "1"}]], "REPORT_ID": "100", "BACK_BUTTON": "loadBackPageWithDate(1,'''''''')", "DATE_FILTER": "H,M,Y", "QUERY_INPUT": {"H": "SELECT TO_CHAR(GEN_DATE, ''HH24'') AS HOUR, SUM(NO_CONTENT_UPLOAD) AS TOTAL_UPLOAD, SUM(NO_CONTENT_DELETE) AS TOTAL_DELETE, SUM(NO_CONTENT_AVAILABLE) AS TOTAL_AVAILABLE FROM IVR_MIS_CONTENT_CUMULATIVE WHERE GEN_DATE BETWEEN TO_TIMESTAMP(''_$fromDate$_'', ''YYYY-MM-DD HH24:MI:SS'') AND TO_TIMESTAMP(''_$toDate$_'', ''YYYY-MM-DD HH24:MI:SS'') GROUP BY TO_CHAR(GEN_DATE, ''HH24'') ORDER BY TO_CHAR(GEN_DATE, ''HH24'')", "M": "SELECT TO_CHAR(GEN_DATE, ''YYYY-MM-DD'') AS REPORT_DATE, SUM(NO_CONTENT_UPLOAD) AS TOTAL_UPLOAD, SUM(NO_CONTENT_DELETE) AS TOTAL_DELETE, SUM(NO_CONTENT_AVAILABLE) AS TOTAL_AVAILABLE FROM IVR_MIS_CONTENT_CUMULATIVE WHERE GEN_DATE BETWEEN TO_TIMESTAMP(''_$fromDate$_'', ''YYYY-MM-DD HH24:MI:SS'') AND TO_TIMESTAMP(''_$toDate$_'', ''YYYY-MM-DD HH24:MI:SS'') GROUP BY TO_CHAR(GEN_DATE, ''YYYY-MM-DD'') ORDER BY TO_CHAR(GEN_DATE, ''YYYY-MM-DD'')", "Y": "SELECT TO_CHAR(GEN_DATE, ''MONTH'') AS MONTH_NAME, TO_CHAR(GEN_DATE, ''MM'') AS MONTH_NO, SUM(NO_CONTENT_UPLOAD) AS TOTAL_UPLOAD, SUM(NO_CONTENT_DELETE) AS TOTAL_DELETE, SUM(NO_CONTENT_AVAILABLE) AS TOTAL_AVAILABLE FROM IVR_MIS_CONTENT_CUMULATIVE WHERE GEN_DATE BETWEEN TO_TIMESTAMP(''_$fromDate$_'', ''YYYY-MM-DD HH24:MI:SS'') AND TO_TIMESTAMP(''_$toDate$_'', ''YYYY-MM-DD HH24:MI:SS'') GROUP BY TO_CHAR(GEN_DATE, ''MONTH''), TO_CHAR(GEN_DATE, ''MM'') ORDER BY TO_CHAR(GEN_DATE, ''MM'')"}, "REPORT_NAME": "Snap Shot", "OTHER_FILTER": [], "PRODUCT_NAME": "IVR", "ROW_TEMPLATE": [{"LINK": "<dateLinkFunctionIfReq>", "DISPLAY": "C1"}, {"DISPLAY": "C2"}, {"DISPLAY": "C3"}, {"DISPLAY": "C4"}, {"DISPLAY": "C3"}, {"DISPLAY": "C4"}], "REPORT_HEADING": "Snap Shot"}'::jsonb);
VALUES(<PRODUCT_ID_VALUE>, 200, 5100, '{"DB_TYPE": "4", "HEADING": [[{"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Date/Time", "ROWSPAN": "2"}, {"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Call Received", "ROWSPAN": "2"}, {"ALIGN": "CENTER", "COLSPAN": "3", "DISPLAY": "Answered", "ROWSPAN": "1"}, {"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Call Rejected", "ROWSPAN": "2"}, {"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Duration[In sec]", "ROWSPAN": "2"}, {"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Average", "ROWSPAN": "2"}], [{"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Total Answered", "ROWSPAN": "1"}, {"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Total Completed", "ROWSPAN": "1"}, {"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Total Disconnected", "ROWSPAN": "1"}]], "REPORT_ID": "500", "BACK_BUTTON": "loadBackPageWithDate(1,'''''''')", "DATE_FILTER": "H,M,Y", "QUERY_INPUT": {"H": "SELECT TO_CHAR(GEN_TIME, ''HH24'') AS C1, COALESCE(SUM(CASE WHEN EVR_CAUSE = 1 THEN COUNT ELSE 0 END), 0) AS C2, COALESCE(SUM(CASE WHEN EVR_CAUSE = 3 THEN COUNT ELSE 0 END), 0) AS C3, COALESCE(SUM(CASE WHEN EVR_CAUSE = 13 THEN COUNT ELSE 0 END), 0) AS C4, COALESCE(SUM(CASE WHEN EVR_CAUSE = 4 THEN COUNT ELSE 0 END), 0) AS C5, COALESCE(SUM(CASE WHEN EVR_CAUSE = 5 THEN COUNT ELSE 0 END), 0) AS C6, COALESCE(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN DURATION ELSE 0 END), 0) AS C7, CASE WHEN COALESCE(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN COUNT ELSE 0 END), 0) = 0 THEN 0 ELSE ROUND(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN DURATION ELSE 0 END)::numeric / NULLIF(SUM(CASE WHEN EVR_CAUSE = 3 THEN COUNT ELSE 0 END), 0), 2) END AS C8 FROM IVR_MIS_CUMULATIVE WHERE GEN_TIME BETWEEN TO_TIMESTAMP(''_$fromDate$_'', ''YYYY-MM-DD HH24:MI:SS'') AND TO_TIMESTAMP(''_$toDate$_'', ''YYYY-MM-DD HH24:MI:SS'') GROUP BY TO_CHAR(GEN_TIME, ''HH24'') ORDER BY TO_CHAR(GEN_TIME, ''HH24'')", "M": "SELECT TO_CHAR(GEN_TIME, ''YYYY-MM-DD'') AS C1, COALESCE(SUM(CASE WHEN EVR_CAUSE = 1 THEN COUNT ELSE 0 END), 0) AS C2, COALESCE(SUM(CASE WHEN EVR_CAUSE = 3 THEN COUNT ELSE 0 END), 0) AS C3, COALESCE(SUM(CASE WHEN EVR_CAUSE = 13 THEN COUNT ELSE 0 END), 0) AS C4, COALESCE(SUM(CASE WHEN EVR_CAUSE = 4 THEN COUNT ELSE 0 END), 0) AS C5, COALESCE(SUM(CASE WHEN EVR_CAUSE = 5 THEN COUNT ELSE 0 END), 0) AS C6, COALESCE(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN DURATION ELSE 0 END), 0) AS C7, CASE WHEN COALESCE(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN COUNT ELSE 0 END), 0) = 0 THEN 0 ELSE ROUND(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN DURATION ELSE 0 END)::numeric / NULLIF(SUM(CASE WHEN EVR_CAUSE = 3 THEN COUNT ELSE 0 END), 0), 2) END AS C8 FROM IVR_MIS_CUMULATIVE WHERE GEN_TIME BETWEEN TO_TIMESTAMP(''_$fromDate$_'', ''YYYY-MM-DD HH24:MI:SS'') AND TO_TIMESTAMP(''_$toDate$_'', ''YYYY-MM-DD HH24:MI:SS'') GROUP BY TO_CHAR(GEN_TIME, ''YYYY-MM-DD'') ORDER BY TO_CHAR(GEN_TIME, ''YYYY-MM-DD'')", "Y": "SELECT TO_CHAR(GEN_TIME, ''Month'') AS C1, COALESCE(SUM(CASE WHEN EVR_CAUSE = 1 THEN COUNT ELSE 0 END), 0) AS C2, COALESCE(SUM(CASE WHEN EVR_CAUSE = 3 THEN COUNT ELSE 0 END), 0) AS C3, COALESCE(SUM(CASE WHEN EVR_CAUSE = 13 THEN COUNT ELSE 0 END), 0) AS C4, COALESCE(SUM(CASE WHEN EVR_CAUSE = 4 THEN COUNT ELSE 0 END), 0) AS C5, COALESCE(SUM(CASE WHEN EVR_CAUSE = 5 THEN COUNT ELSE 0 END), 0) AS C6, COALESCE(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN DURATION ELSE 0 END), 0) AS C7, CASE WHEN COALESCE(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN COUNT ELSE 0 END), 0) = 0 THEN 0 ELSE ROUND(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN DURATION ELSE 0 END)::numeric / NULLIF(SUM(CASE WHEN EVR_CAUSE = 3 THEN COUNT ELSE 0 END), 0), 2) END AS C8 FROM IVR_MIS_CUMULATIVE WHERE GEN_TIME BETWEEN TO_TIMESTAMP(''_$fromDate$_'', ''YYYY-MM-DD HH24:MI:SS'') AND TO_TIMESTAMP(''_$toDate$_'', ''YYYY-MM-DD HH24:MI:SS'') GROUP BY TO_CHAR(GEN_TIME, ''Month''), TO_CHAR(GEN_TIME, ''MM'') ORDER BY TO_CHAR(GEN_TIME, ''MM'')"}, "REPORT_NAME": "Snap Shot", "OTHER_FILTER": [], "PRODUCT_NAME": "IVR", "ROW_TEMPLATE": [{"LINK": "<dateLinkFunctionIfReq>", "DISPLAY": "C1"}, {"DISPLAY": "C2"}, {"DISPLAY": "C3"}, {"DISPLAY": "C4"}, {"DISPLAY": "C5"}, {"DISPLAY": "C6"}, {"DISPLAY": "C7"}, {"DISPLAY": "C8"}], "REPORT_HEADING": "Snap Shot"}'::jsonb);
VALUES(<PRODUCT_ID_VALUE>, 300, 5100, '{"DB_TYPE": "4", "HEADING": [[{"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Date/Time", "ROWSPAN": "2"}, {"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Call Received", "ROWSPAN": "2"}, {"ALIGN": "CENTER", "COLSPAN": "3", "DISPLAY": "Answered", "ROWSPAN": "1"}, {"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Call Rejected", "ROWSPAN": "2"}, {"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Duration[In sec]", "ROWSPAN": "2"}, {"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Average", "ROWSPAN": "2"}], [{"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Total Answered"}, {"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Total Completed"}, {"ALIGN": "CENTER", "COLSPAN": "1", "DISPLAY": "Total Disconnected"}]], "REPORT_ID": "500", "BACK_BUTTON": "loadBackPageWithDate(1,'''''''')", "DATE_FILTER": "H,M,Y", "QUERY_INPUT": {"H": "SELECT TO_CHAR(GEN_TIME, ''HH24'') AS C1, COALESCE(SUM(CASE WHEN EVR_CAUSE = 1 THEN COUNT ELSE 0 END), 0) AS C2, COALESCE(SUM(CASE WHEN EVR_CAUSE = 3 THEN COUNT ELSE 0 END), 0) AS C3, COALESCE(SUM(CASE WHEN EVR_CAUSE = 13 THEN COUNT ELSE 0 END), 0) AS C4, COALESCE(SUM(CASE WHEN EVR_CAUSE = 4 THEN COUNT ELSE 0 END), 0) AS C5, COALESCE(SUM(CASE WHEN EVR_CAUSE = 5 THEN COUNT ELSE 0 END), 0) AS C6, COALESCE(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN DURATION ELSE 0 END), 0) AS C7, CASE WHEN COALESCE(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN COUNT ELSE 0 END), 0) = 0 THEN 0 ELSE ROUND(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN DURATION ELSE 0 END)::numeric / NULLIF(SUM(CASE WHEN EVR_CAUSE = 3 THEN COUNT ELSE 0 END), 0), 2) END AS C8 FROM IVR_MIS_CUMULATIVE WHERE GEN_TIME BETWEEN TO_TIMESTAMP(''_$fromDate$_'', ''YYYY-MM-DD HH24:MI:SS'') AND TO_TIMESTAMP(''_$toDate$_'', ''YYYY-MM-DD HH24:MI:SS'') AND ((''_$ShortCodeName$_'' != ''-1'' AND SHORT_CODE = ''_$ShortCodeName$_'') OR ''_$ShortCodeName$_'' = ''-1'') GROUP BY TO_CHAR(GEN_TIME, ''HH24'') ORDER BY TO_CHAR(GEN_TIME, ''HH24'')", "M": "SELECT TO_CHAR(GEN_TIME, ''YYYY-MM-DD'') AS C1, COALESCE(SUM(CASE WHEN EVR_CAUSE = 1 THEN COUNT ELSE 0 END), 0) AS C2, COALESCE(SUM(CASE WHEN EVR_CAUSE = 3 THEN COUNT ELSE 0 END), 0) AS C3, COALESCE(SUM(CASE WHEN EVR_CAUSE = 13 THEN COUNT ELSE 0 END), 0) AS C4, COALESCE(SUM(CASE WHEN EVR_CAUSE = 4 THEN COUNT ELSE 0 END), 0) AS C5, COALESCE(SUM(CASE WHEN EVR_CAUSE = 5 THEN COUNT ELSE 0 END), 0) AS C6, COALESCE(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN DURATION ELSE 0 END), 0) AS C7, CASE WHEN COALESCE(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN COUNT ELSE 0 END), 0) = 0 THEN 0 ELSE ROUND(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN DURATION ELSE 0 END)::numeric / NULLIF(SUM(CASE WHEN EVR_CAUSE = 3 THEN COUNT ELSE 0 END), 0), 2) END AS C8 FROM IVR_MIS_CUMULATIVE WHERE GEN_TIME BETWEEN TO_TIMESTAMP(''_$fromDate$_'', ''YYYY-MM-DD HH24:MI:SS'') AND TO_TIMESTAMP(''_$toDate$_'', ''YYYY-MM-DD HH24:MI:SS'') AND ((''_$ShortCodeName$_'' != ''-1'' AND SHORT_CODE = ''_$ShortCodeName$_'') OR ''_$ShortCodeName$_'' = ''-1'') GROUP BY TO_CHAR(GEN_TIME, ''YYYY-MM-DD'') ORDER BY TO_CHAR(GEN_TIME, ''YYYY-MM-DD'')", "Y": "SELECT TO_CHAR(GEN_TIME, ''Month'') AS C1, COALESCE(SUM(CASE WHEN EVR_CAUSE = 1 THEN COUNT ELSE 0 END), 0) AS C2, COALESCE(SUM(CASE WHEN EVR_CAUSE = 3 THEN COUNT ELSE 0 END), 0) AS C3, COALESCE(SUM(CASE WHEN EVR_CAUSE = 13 THEN COUNT ELSE 0 END), 0) AS C4, COALESCE(SUM(CASE WHEN EVR_CAUSE = 4 THEN COUNT ELSE 0 END), 0) AS C5, COALESCE(SUM(CASE WHEN EVR_CAUSE = 5 THEN COUNT ELSE 0 END), 0) AS C6, COALESCE(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN DURATION ELSE 0 END), 0) AS C7, CASE WHEN COALESCE(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN COUNT ELSE 0 END), 0) = 0 THEN 0 ELSE ROUND(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN DURATION ELSE 0 END)::numeric / NULLIF(SUM(CASE WHEN EVR_CAUSE = 3 THEN COUNT ELSE 0 END), 0), 2) END AS C8 FROM IVR_MIS_CUMULATIVE WHERE GEN_TIME BETWEEN TO_TIMESTAMP(''_$fromDate$_'', ''YYYY-MM-DD HH24:MI:SS'') AND TO_TIMESTAMP(''_$toDate$_'', ''YYYY-MM-DD HH24:MI:SS'') AND ((''_$ShortCodeName$_'' != ''-1'' AND SHORT_CODE = ''_$ShortCodeName$_'') OR ''_$ShortCodeName$_'' = ''-1'') GROUP BY TO_CHAR(GEN_TIME, ''Month''), TO_CHAR(GEN_TIME, ''MM'') ORDER BY TO_CHAR(GEN_TIME, ''MM'')"}, "REPORT_NAME": "Short Code", "OTHER_FILTER": [{"TYPE": "S", "DISPLAY": "Short Code", "FILTER_QUERY": {"QUERY": "SELECT DISTINCT ICU.SHORT_CODE AS C1, ISC.DISPLAY AS C2 FROM IVR_MIS_CUMULATIVE ICU JOIN IVR_SHORT_CODE_MAST ISC ON TRIM(ICU.SHORT_CODE) = ISC.SHORT_CODE", "DATA_ID": "C1", "DATA_LABEL": "C2", "QUERY_PARAM_VALUE": "C1"}, "QUERY_PARAM_NAME": "ShortCodeName"}], "PRODUCT_NAME": "IVR", "ROW_TEMPLATE": [{"LINK": "<dateLinkFunctionIfReq>", "DISPLAY": "C1"}, {"DISPLAY": "C2"}, {"DISPLAY": "C3"}, {"DISPLAY": "C4"}, {"DISPLAY": "C5"}, {"DISPLAY": "C6"}, {"DISPLAY": "C7"}, {"DISPLAY": "C8"}], "REPORT_HEADING": "Short Code"}'::jsonb);

